import numpy as np

def objects(g):
    a=np.array(g); res=[]
    for c in [int(x) for x in np.unique(a) if x]:
        lab,n=label(a==c)
        for i in range(1,n+1):
            ys,xs=np.where(lab==i)
            r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
            shape=[[(int(a[y,x])==c) for x in range(c0,c1+1)] for y in range(r0,r1+1)]
            res.append(dict(color=c,r0=int(r0),c0=int(c0),shape=shape))
    return res

def has_hole(shape):
    h,w=len(shape),len(shape[0])
    import numpy as np
    z=np.array([[not shape[y][x] for x in range(w)] for y in range(h)])
    # flood from border
    from scipy.ndimage import label as L
    lab,n=L(z)
    border={lab[0,x] for x in range(w)}|{lab[h-1,x] for x in range(w)}|{lab[y,0] for y in range(h)}|{lab[y,w-1] for y in range(h)}
    border.discard(0)
    return any(lab[y,x] not in border and lab[y,x]!=0 for y in range(h) for x in range(w))

