    out=[[0]*W for _ in range(H)]
    occ=[[False]*W for _ in range(H)]
    objs=objects(g)
    for o in objs: o['hollow']=has_hole(o['shape'])
    def fits(shape,r0,c0):
        for y,row in enumerate(shape):
            for x,v in enumerate(row):
                if v and (r0+y>=H or occ[r0+y][c0+x]): return False
        return True
    def place(o,up):
        h=len(o['shape'])
        rng=range(0,H-h+1) if up else range(H-h,-1,-1)
        for r0 in rng:
            if fits(o['shape'],r0,o['c0']):
                for y,row in enumerate(o['shape']):
                    for x,v in enumerate(row):
                        if v: out[r0+y][o['c0']+x]=o['color']; occ[r0+y][o['c0']+x]=True
                return
    for o in sorted([o for o in objs if o['hollow']],key=lambda o:o['r0']): place(o,True)
    for o in sorted([o for o in objs if not o['hollow']],key=lambda o:o['r0']): place(o,False)
    return out

